entries[1224964] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nMana-Tinted Glasses\nBrann dons mana-tinted glasses while in combat, periodically increasing his damage done by 4 % and damage taken by 5 % every 5 sec up to 10 times.\n\nDispelling the glasses will heal Brann for 25 % of his maximum health and stun nearby enemies for 2 sec.\nOtherwise this effect is automatically dispelled when Brann drops below 30 % health which prevents the stun from occurring.\n\nYou already have this curio in your collection." }
