entries[1225061] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nSands of K'aresh\nWhen Brann uses Gathering Tools , sands begin swirling around party members, granting 6 % Critical Strike up to 10 times and slowing nearby enemies by 6 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[1225062] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nSands of K'aresh\nWhen Brann uses Gathering Tools , sands begin swirling around party members, granting 8 % Critical Strike up to 10 times and slowing nearby enemies by 8 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[1225063] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nSands of K'aresh\nWhen Brann uses Gathering Tools , sands begin swirling around party members, granting 10 % Critical Strike up to 10 times and slowing nearby enemies by 10 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[1225064] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nSands of K'aresh\nWhen Brann uses Gathering Tools , sands begin swirling around party members, granting 12 % Critical Strike up to 10 times and slowing nearby enemies by 12 %.\n\nDealing a Critical Strike creates a Sand Devil at the target's location for 6 sec that periodically pulls enemies to its center. Can only occur every 45 sec.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[1225065] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTemporal Decelerator Crystal\nDamaging an Elite at 80 % or above and at 20 % or below health causes Brann to trigger the crystal's energies, reducing the Elite's attack and cast speed by 20 % for 30 sec. Killing the targeted Elite while the debuff is active grants the party an 2 % stacking Haste buff.\n\nYou already have this curio in your collection." }
entries[1225066] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTemporal Decelerator Crystal\nDamaging an Elite at 80 % or above and at 20 % or below health causes Brann to trigger the crystal's energies, reducing the Elite's attack and cast speed by 30 % for 30 sec. Killing the targeted Elite while the debuff is active grants the party an 4 % stacking Haste buff.\n\nYou already have this curio in your collection." }
entries[1225067] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTemporal Decelerator Crystal\nDamaging an Elite at 80 % or above and at 20 % or below health causes Brann to trigger the crystal's energies, reducing the Elite's attack and cast speed by 40 % for 30 sec. Killing the targeted Elite while the debuff is active grants the party an 6 % stacking Haste buff.\n\nYou already have this curio in your collection." }
entries[1225068] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTemporal Decelerator Crystal\nDamaging an Elite at 80 % or above and at 20 % or below health causes Brann to trigger the crystal's energies, reducing the Elite's attack and cast speed by 50 % for 30 sec. Killing the targeted Elite while the debuff is active grants the party an 8 % stacking Haste buff.\n\nYou already have this curio in your collection." }
entries[1225069] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBattered Aegis\nWhile the Aegis is equipped, all party members deal 3 % increased damage and healing. Every 10 sec during combat, you and Brann heal for 5 % of the damage you've taken during that time.\n\nWhen a player dies, the Aegis grants them 1 % damage reduction and 2 % increased healing received upon revival, but reduces their damage and healing dealt by 1 % stacking up to 3 times.\n\nYou already have this curio in your collection." }
entries[1225070] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBattered Aegis\nWhile the Aegis is equipped, all party members deal 6 % increased damage and healing. Every 10 sec during combat, you and Brann heal for 10 % of the damage you've taken during that time.\n\nWhen a player dies, the Aegis grants them 2 % damage reduction and 3 % increased healing received upon revival, but reduces their damage and healing dealt by 2 % stacking up to 3 times.\n\nYou already have this curio in your collection." }
entries[1225072] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBattered Aegis\nWhile the Aegis is equipped, all party members deal 9% increased damage and healing. Every 10 sec during combat, you and Brann heal for 15% of the damage you've taken during that time.\n\nWhen a player dies, the Aegis grants them 3% damage reduction and 4% increased healing received upon revival, but reduces their damage and healing dealt by 3% stacking up to 3 times.\n\nYou already have this curio in your collection." }
entries[1225073] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBattered Aegis\nWhile the Aegis is equipped, all party members deal 12 % increased damage and healing. Every 10 sec during combat, you and Brann heal for 20 % of the damage you've taken during that time.\n\nWhen a player dies, the Aegis grants them 4 % damage reduction and 5 % increased healing received upon revival, but reduces their damage and healing dealt by 4 % stacking up to 3 times.\n\nYou already have this curio in your collection." }
