entries[1225312] = { ["name"] = "Amassing Voidlust", ["text"] = "Instant\nHarness the violent energy that permeates the Voidstorm, occasionally triggering a power suffusion of cosmic energy.\n\nWhen embraced, the energy erupts in a state called Voidlust.\n\nVoidlust\nBecome infused with ambient Void energies.\n\nIncrease your chance to critically strike by 25%.\nIncrease leech by 5%.\nIncrease movement speed by 10%." }
entries[1225315] = { ["name"] = "Galactic Smash", ["text"] = "Unlimited range\nInstant\nImages of Salhadaar emerge alongside him to smash their targets with galactic force, applying Twilight Scar and inflicting 12142510 Cosmic damage to all players. Players farther from each target take less damage.\n\nSalhadaar's primary target is Starshattered . A Dark Star forms at each impact location." }
