entries[1225335] = { ["name"] = "Zul'Aman", ["text"] = "Instant\nRecommended Skill: 100\n\n\"Hunt or be hunted\" defines the rule for Zul'Aman. Highly aggressive fish offer increased risk and reward for Anglers ready to accept greater challenges.\n\nPools found in this zone:\n- Surface Ripple\n- Obscured School\n- Hunter Surge\n- Viscous Void\n- Careless Cargo\n- Lost Treasures\nProfession:\nFishing (75)" }
entries[1225336] = { ["name"] = "Voidstorm", ["text"] = "Instant\nRecommended Skill: 300\n\nOtherworldly and obscure. Fishing here is truly explorative. Can you cast a line? Absolutely. Is it safe? That's anybody's guess. Masses of liquid void call the most daring Anglers to set their bobbers and wait for whatever surprises unfold.\n\nPools found in this zone:\n- Oceanic Vortex\nProfession:\nFishing (225)" }
entries[1225337] = { ["name"] = "Harandar", ["text"] = "Instant\nRecommended Skill: 225\n\nA bioluminescent ecosystem of intertwined roots and Lightbloom. Shimmering waters mix with decay and other plant life to create a uniquely dynamic set of inhabitants.\n\nPools found in this zone:\n- Blossoming Torrent\n- Lashing Waves\n- Viscous Void\n- Careless Cargo\n- Lost Treasures\nProfession:\nFishing (150)" }
entries[1225339] = { ["name"] = "Web Strand", ["text"] = "5 yd range\nInstant\nHolding web wrapped around a Webbed Scout. Pull to free them!" }
entries[1225340] = { ["name"] = "Midnight Anglin'", ["text"] = "5 yd range\n3.2 sec cast\nBecoming an Angler is easy!\n\nCast your line and reel in the many secrets Midnight has to offer.\n\nCaught Fish will appear here in your trusty Fishing Journal. The records here will detail these fanciful fish and give indication on where you might find them again!" }
entries[1225342] = { ["name"] = "Studying", ["text"] = "1.5 sec cast\nStudy to increase your Midnight Herbalism Knowledge by 1." }
entries[1225343] = { ["name"] = "Refulgent Copper", ["text"] = "5 yd range\n2.5 sec cast\nCopper veins have long populated Azeroth. Through a combination of advances in Mining techniques and copper veins bathing in magical energies, the newly-dubbed Refulgent Copper is quickly becoming an essential metal in Quel'Thalas.\nDiscovery:\nMidnight Gathering Nodes" }
entries[1225344] = { ["name"] = "Studying", ["text"] = "1.5 sec cast\nStudy to increase your Midnight Herbalism Knowledge by 4." }
