entries[1225897] = { ["name"] = "Void-Tempered Scales", ["text"] = "5 yd range\n2.5 sec cast\nWhere there isn't leather there's scales. Between fish, snakes, dragonhawks, and monstrous void creatures, there is plenty of material to make toughened scale armor." }
entries[1225901] = { ["name"] = "Void-Tempered Leather", ["text"] = "5 yd range\n2.5 sec cast\nFrom Thalassian lynxes and Hawkstriders to Amani bears, this tough, pliable resource is utilized in the creation of various pieces of equipment." }
entries[1225902] = { ["name"] = "Void-Tempered Hide", ["text"] = "5 yd range\n2.5 sec cast\nSometimes a skinner can recover a particularly superb sample of leather from a skinnable creature. These hides are used in more potent crafts, or in places where standard leather just won't do the job." }
entries[1225903] = { ["name"] = "Void-Tempered Plating", ["text"] = "5 yd range\n2.5 sec cast\nSkinners can rarely acquire superb sheets of scales referred to as plating from scaled creatures. These are potent reagents that are used in more complex recipes where run-of-the-mill scales just won't do." }
entries[1225908] = { ["name"] = "Fine Void-Tempered Hide", ["text"] = "5 yd range\n5.3 sec cast\nThere are some hides that won't stand up to the needs of equipment crafting. While they may be fantastic specimens, they lack the structural integrity or have some other flaw that makes them unfortunately lackluster for more practical uses. They are however fantastic for studying and gaining anatomical knowledge.\n\nYou may discover 5 more fine hide(s) this week." }
