entries[1226031] = { ["name"] = "Poison Splash", ["text"] = "100 yd range\nInstant\nAtroxus splashes poison around itself, inflicting 43642 Nature damage to all enemies every 1 sec.\n\nThe poison glob inflicts 193965 Nature damage and an additional 58189 Nature damage every 1 sec for 5 sec to players struck. Each impact creates a poison pool for 1 min." }
entries[1226033] = { ["name"] = "Eradicate", ["text"] = "Fully channeling Void Ray upgrades your Reap to Eradicate.\n\nEradicate\nSlam your Scythe to the ground, dealing (557% of Spell Power) Cosmic damage to your primary target and [(557% of Spell Power) * 0.9] to all other enemies within a 25 yd cone in front of you. Damage reduced beyond 5 targets.\n\nEradicate gathers up to 4 nearby souls." }
